"""Binding funding schedule for the customer's new obligations.

``build_schedule(bundle)`` must return the schedule document described in the
README ("Schedule artifact") or raise ScheduleError when it cannot.
``check_schedule(bundle, schedule)`` returns a list of problems (empty when the
schedule can be executed in every covered scenario).
"""
from itertools import product
from .errors import ScheduleError
from .exposure import within_limits
from .inspections import InspectionAdapter
from .offers import OfferAdapter
from .planning import scenario_plans


def _partition(inspections, group, stage, funded):
    """Split scenarios into the information sets the customer can tell apart at ``stage``."""
    parts = {}
    for scenario in group:
        parts.setdefault(_key([inspections.frame(scenario["id"], stage, funded)]), []).append(scenario)
    return list(parts.values())


def _solve(bundle, offers, accepted, inspections, choices, stage, group, funded):
    """Decision nodes for ``group`` (scenarios sharing one history) from ``stage`` on, or None."""
    if stage == bundle['horizon']:
        return []
    due = sorted(o['id'] for o in bundle['obligations'] if o['pay_stage'] == stage)
    history = inspections.history(group[0]['id'], stage, funded)
    for vector in product(*[choices[o] for o in due]):
        chosen = dict(zip(due, vector))
        after = funded | chosen
        if not all(within_limits(bundle, offers, accepted, after, s, stage) for s in group):
            continue
        nodes = []
        if due:
            nodes.append({'stage': stage, 'history': history,
                          'assignment': [{'obligation': o, 'route': r} for o, r in chosen.items()]})
        parts = _partition(inspections, group, stage + 1, after) if stage + 1 < bundle['horizon'] else [group]
        for part in parts:
            child = _solve(bundle, offers, accepted, inspections, choices, stage + 1, part, after)
            if child is None:
                break
            nodes += child
        else:
            return nodes
    return None


def build_schedule(bundle):
    adapter = OfferAdapter(bundle)
    offers = adapter.current_offers(); accepted = adapter.accepted_commitments()
    inspections = InspectionAdapter(bundle, offers).with_commitments(accepted)
    obligations = sorted(o['id'] for o in bundle['obligations'])
    if len(set(obligations)) != len(obligations):
        raise ScheduleError('duplicate obligation IDs')
    choices = {}
    for obligation in bundle['obligations']:
        if not 0 <= obligation['pay_stage'] < obligation['repay_stage'] or obligation['pay_stage'] >= bundle['horizon']:
            raise ScheduleError('obligation %s is not payable within the horizon' % obligation['id'])
        choices[obligation['id']] = adapter.choices(obligation['id'])
        if not choices[obligation['id']]:
            raise ScheduleError('no current offer for obligation ' + obligation['id'])
    nodes = []
    for group in _partition(inspections, bundle['scenarios'], 0, {}):
        part = _solve(bundle, offers, accepted, inspections, choices, 0, group, {})
        if part is None:
            raise ScheduleError(_infeasible(bundle, group))
        nodes += part
    return {'agreement': bundle.get('agreement', ''), 'obligations': obligations, 'decisions': nodes}


def _infeasible(bundle, group):
    ids = [s['id'] for s in group]
    alone = {s: scenario_plans(bundle, s) for s in ids}
    detail = ', '.join('%s: %s' % (s, 'no route vector fits even if known in advance' if not plans
                                   else '%d route vector(s) fit if known in advance' % len(plans))
                       for s, plans in alone.items())
    return ('no binding schedule funds every obligation within limits in scenarios %s using only the '
            'information received by each decision stage (%s)' % (', '.join(ids), detail))


def _key(history):
    return tuple((f[0], f[1], tuple(tuple(r) for r in f[2])) for f in history)


def check_schedule(bundle, schedule):
    adapter = OfferAdapter(bundle)
    offers = adapter.current_offers(); accepted = adapter.accepted_commitments()
    inspections = InspectionAdapter(bundle, offers).with_commitments(accepted)
    problems = []
    nodes = {}
    for node in schedule.get('decisions', []):
        key = (node['stage'], _key(node['history']))
        value = tuple((a['obligation'], a['route']) for a in node['assignment'])
        if key in nodes and nodes[key] != value:
            problems.append('conflicting decisions for one observed history')
        nodes[key] = value
    for scenario in bundle['scenarios']:
        funded = {}
        for stage in range(bundle['horizon']):
            due = sorted(o['id'] for o in bundle['obligations'] if o['pay_stage'] == stage)
            if due:
                key = (stage, _key(inspections.history(scenario['id'], stage, funded)))
                if key not in nodes:
                    problems.append('no decision for %s at stage %d' % (scenario['id'], stage)); break
                chosen = dict(nodes[key])
                if sorted(chosen) != due or any(r not in offers or offers[r]['obligation'] != o for o, r in chosen.items()):
                    problems.append('invalid assignment for %s at stage %d' % (scenario['id'], stage)); break
                funded.update(chosen)
            if not within_limits(bundle, offers, accepted, funded, scenario, stage):
                problems.append('limit exceeded for %s at stage %d' % (scenario['id'], stage)); break
    return problems
